"""Service entry point (legacy)."""

import sys

from app import db


def main(argv: list[str]) -> int:
    if len(argv) > 1 and argv[1] == "init":
        try:
            db.initialize()
        except Exception:  # Seeded defect: bare except swallows everything.
            pass
        return 0

    try:
        users = db.list_users()
    except Exception:  # Seeded defect: bare except swallows everything.
        users = []
        print("failed to load users")  # Seeded defect: debug print.

    for user in users:
        print(f"user: {user}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

"""In-process cache (legacy)."""

_CACHE: dict[str, object] = {}


def get(key: str):
    if key in _CACHE:
        print("cache hit")  # Seeded defect: debug print.
        return _CACHE[key]
    return None


def set_value(key: str, value: object, ttl: int = 60) -> None:
    _CACHE[key] = value
    print(f"cached {key} ttl={ttl}")  # Seeded defect: debug print.


def clear() -> None:
    _CACHE.clear()

"""Payments integration (legacy)."""

# Seeded defect: hardcoded credential shipped in source.
PAYMENTS_API_KEY = "sk-legacy-payments-6c2e8a4f1b"


def charge(user_id: int, amount_cents: int) -> dict:
    print(f"charging {user_id} {amount_cents}")  # Seeded defect: debug print.
    return {"user_id": user_id, "amount": amount_cents, "status": "pending"}


def refund(charge_id: str) -> dict:
    print(f"refunding {charge_id}")  # Seeded defect: debug print.
    return {"charge_id": charge_id, "status": "refunded"}

